`,J8e=`/**
 * SideEffect - side effect container (never auto-executed)
 */
export class SideEffect<T = unknown> {
  readonly effect: () => T;
  readonly label?: string;

  constructor(effect: () => T, label?: string) {
    this.effect = effect;
    this.label = label;
  }

  static of<T>(effect: () => T, label?: string): SideEffect<T> {
    return new SideEffect(effect, label);
  }
}

export type MatchHandlers<T, RValue, REffect, E = unknown> = {
  value: (value: T) => RValue;
  effect: (sideEffect: SideEffect<E>) => REffect;
};

type EffectValue<T> = T extends SideEffect<infer E> ? (0 extends 1 & E ? unknown : E) : never;
export function matchSideEffect<Input, RValue, REffect>(
  result: Input,
  handlers: MatchHandlers<Exclude<Input, SideEffect<any>>, RValue, REffect, EffectValue<Input>>
): RValue | REffect;
export function matchSideEffect<T, RValue, REffect = unknown, E = unknown>(
  result: T | SideEffect<E>,
  handlers: MatchHandlers<T, RValue, REffect, E>
): RValue | REffect;
export function matchSideEffect<T, RValue, REffect = any>(
  result: T | SideEffect,
  handlers: MatchHandlers<T, RValue, REffect>
): RValue | REffect {
  if (result instanceof SideEffect) {
    return handlers.effect(result);
  }
  return handlers.value(result as T);
}

export function runPipeResult<_T, R>(result: SideEffect<R>): R;
export function runPipeResult<T>(result: T): T extends SideEffect<infer R> ? R : T;
export function runPipeResult<T, R = any>(result: T | SideEffect<R>): T | R;
export function runPipeResult<T, R = any>(result: T | SideEffect<R>): T | R {
  if (isSideEffect(result)) {
    return result.effect() as R;
  }
  return result as T;
}

export function isSideEffect(value: unknown): value is SideEffect<any> {
  return value instanceof SideEffect;
}

export default SideEffect;
`,X8e=`/**
 * tap - 값을 그대로 흘리며 side-effect 실행
 */
function tap<T>(fn: (value: T) => void): (value: T) => T {
  return (value: T) => {
    fn(value);
    return value;
  };
}

export default tap;
`,Y8e=`/**
 * tap0 - 입력 없이 side-effect 실행
 */
function tap0(fn: () => void): () => void {
  return () => {
    fn();
  };
}

export default tap0;
`,$8e=`/**
 * cond - 다중 조건 분기 (switch 대체)
 */
function cond<T, R>(
  conditions: ReadonlyArray<readonly [(value: T) => boolean, (value: T) => R]>
): (value: T) => R | undefined;
function cond<T, R extends readonly unknown[]>(
  conditions: readonly [...{ [K in keyof R]: readonly [(value: T) => boolean, (value: T) => R[K]] }]
): (value: T) => R[number] | undefined;
function cond<T, R>(
  conditions: ReadonlyArray<readonly [(value: T) => boolean, (value: T) => R]>
): (value: T) => R | undefined {
  return (value: T) => {
    for (const [predicate, handler] of conditions) {
      if (predicate(value)) {
        return handler(value);
      }
    }
    return undefined;
  };
}

export default cond;
